function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 - 100, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw water droplets
  for (let i = 0; i < 10; i++) {
    ctx.fillStyle = 'blue';
    ctx.beginPath();
    ctx.arc(W / 2 + Math.cos(t + i) * 100, H / 2 + Math.sin(t + i) * 100, 10, 0, 2 * Math.PI);
    ctx.fill();
    ctx.stroke();
  }

  // draw plant
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.rect(W / 2 - 20, H / 2 + 50, 40, 100);
  ctx.fill();
  ctx.stroke();

  // draw roots
  ctx.beginPath();
  ctx.moveTo(W / 2 - 20, H / 2 + 150);
  ctx.lineTo(W / 2 - 50, H / 2 + 200);
  ctx.lineTo(W / 2 + 10, H / 2 + 200);
  ctx.lineTo(W / 2 - 20, H / 2 + 150);
  ctx.fill();
  ctx.stroke();

  // draw stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W / 2 - 150, H / 2 - 50, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 150, H / 2 - 30);
  ctx.lineTo(W / 2 - 150, H / 2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 150, H / 2);
  ctx.lineTo(W / 2 - 120, H / 2 - 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 150, H / 2);
  ctx.lineTo(W / 2 - 180, H / 2 - 20);
  ctx.stroke();

  ctx.restore();
}
